<?php
declare(strict_types=1);

function authErrorPage(string $message,string $reason='error',string $email=''): string
{
    $esc=static fn(string $s):string=>htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
    $membership=in_array($reason,['unknown','disabled'],true);
    $title=match($reason){'unknown'=>'Your email is not on the team sheet.','disabled'=>'Your club access is paused.',default=>'Let’s get you back to the clubhouse.'};
    $intro=match($reason){'unknown'=>'This email address is not registered as a club member yet.','disabled'=>'Your membership is currently disabled. A board member can help you check your access.',default=>$message};
    $emailBlock=$membership&&$email!==''?'<div class="auth-account"><span>Google account</span><strong>'.$esc($email).'</strong></div>':'';
    $guidance=$membership?'<section class="auth-board-help" aria-labelledby="board-access-title"><h2 id="board-access-title">Ask the board for access</h2><p>Access is arranged by the team managers — your club’s board members. Contact one of them and ask to have your email address added to the club.</p><p>Already a player? Ask them to link this email to your existing player profile, so your games, payments and statistics stay together.</p></section>':'<div class="auth-board-help"><p>Try signing in again. If the problem continues, ask a board member for help.</p></div>';
    $action=$membership?'Use another Google account':'Try signing in again';
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><meta name="theme-color" content="#123e34"><link rel="icon" href="/club-crest.svg" type="image/svg+xml"><link rel="stylesheet" href="/club.css?v=20261101-auth-error1"><title>'.$esc($membership?'Member access':'Sign-in help').' · FC Castellón</title></head><body class="auth-help-page"><a class="skip-link" href="#content">Skip to content</a><div class="login-page"><aside class="login-story"><div class="auth-help-pitch" aria-hidden="true"></div><a class="identity" href="/"><img src="/club-crest.svg" alt="FC Castellón crest" width="43" height="51"><div><strong>FC Castellón</strong><small>THE CLUBHOUSE</small></div></a><div><h1>For the football.<br><em>For the people.</em></h1><p>A place for your football.<br>A club for your people.</p></div><footer>GOOD FOOTBALL. BETTER COMPANY.</footer></aside><main class="login-form" id="content"><div class="login-box auth-help-box"><div class="eyebrow">'.($membership?'A place in the club':'Sign-in help').'</div><div class="auth-help-symbol" aria-hidden="true">⚽</div><h1>'.$esc($title).'</h1><p class="auth-help-intro">'.$esc($intro).'</p>'.$emailBlock.$guidance.'<div class="auth-help-actions"><a class="btn btn-primary" href="/api/auth/google.php">'.$action.'</a><a class="btn btn-outline" href="/">Back to sign-in</a></div><p class="login-note">Choose the Google account or membership email registered with the club.</p></div></main></div></body></html>';
}
